public int SingleNumberII(int[] nums) {        // #137: all three times, one once
    int ans = 0;
    for (int k = 0; k < 32; k++) {
        int count = 0;
        foreach (int v in nums) count += (v >> k) & 1;
        if (count % 3 != 0) ans |= 1 << k;      // triples give a multiple of three
    }
    return ans;                                 // bit 31 is collected too: negatives work
}
